import{_ as t,o as s,c as o,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — Assign Task To Creator","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-2-assign-task-to-creator/sequence-flow.md","filePath":"feature/content-task-workflow/3-6-2-assign-task-to-creator/sequence-flow.md"}'),r={name:"feature/content-task-workflow/3-6-2-assign-task-to-creator/sequence-flow.md"};function i(c,e,d,l,n,k){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="sequence-flow-—-assign-task-to-creator" tabindex="-1">Sequence Flow — Assign Task To Creator <a class="header-anchor" href="#sequence-flow-—-assign-task-to-creator" aria-label="Permalink to &quot;Sequence Flow — Assign Task To Creator&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.6.2). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those).</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Manager</strong> — actor tương tác chính trong quy trình.</li><li><strong>Client</strong> — giao diện người dùng <code>TaskDetailUI</code>.</li><li><strong>System</strong> — <code>TaskController</code> / <code>TaskService</code>.</li></ul><hr><h2 id="flow-a-—-luong-thuc-thi-chinh-assign-task-to-creator" tabindex="-1">Flow A — Luồng thực thi chính: Assign Task To Creator <a class="header-anchor" href="#flow-a-—-luong-thuc-thi-chinh-assign-task-to-creator" aria-label="Permalink to &quot;Flow A — Luồng thực thi chính: Assign Task To Creator&quot;">​</a></h2><ol><li>manager -&gt; taskdetailui: <code>clicks &quot;Assign Task&quot; button on task detail page</code></li><li>taskdetailui -&gt; taskcontroller: <code>GET /api/v1/workspaces/{workspaceId}/members?role=MEMBER</code></li><li>taskcontroller -&gt; taskservice: <code>listAssignableMembers(workspaceId)</code></li><li>taskservice -&gt; workspacememberrepos: <code>findAllByWorkspaceIdAndStatusActive(workspaceId)</code></li><li>workspacememberrepos --&gt; taskservice: <code>activeMemberList</code></li><li>taskservice --&gt; taskcontroller: <code>List&lt;WorkspaceMemberResponse&gt;</code></li><li>taskcontroller --&gt; taskdetailui: <code>200 OK (activeMemberList)</code></li><li>taskdetailui --&gt; manager: <code>render Assign dialog (assignee dropdown, QC dropdown, requireClientApproval toggle)</code></li><li>manager -&gt;&gt; taskdetailui: <code>selects assigneeId, optional qcAssigneeId, toggles requiresClientApproval &amp; submits</code></li><li>taskdetailui -&gt;&gt; taskcontroller: <code>POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/assign (AssignTaskRequest)</code></li><li>taskcontroller -&gt;&gt; taskservice: <code>assignTask(workspaceId, taskId, currentUser, request)</code></li><li>taskservice -&gt;&gt; taskrepository: <code>findByIdAndWorkspaceId(taskId, workspaceId)</code></li><li>taskrepository --&gt; taskservice: <code>task</code></li><li>taskservice --&gt; taskcontroller: <code>throw BusinessException (403 FORBIDDEN)</code></li><li>taskdetailui --&gt; manager: <code>show access denied error toast</code></li><li>taskcontroller --&gt; taskdetailui: <code>403 Forbidden</code></li><li>taskservice --&gt; taskcontroller: <code>throw BusinessException (409 TASK_DETAIL_NOT_IDENTIFIED)</code></li><li>taskdetailui --&gt; manager: <code>show error alert (&quot;Task must be in DETAIL_IDENTIFIED status before assignment&quot;)</code></li><li>taskcontroller --&gt; taskdetailui: <code>409 Conflict</code></li><li>taskservice --&gt; taskcontroller: <code>throw BusinessException (400 QC_CANNOT_BE_SAME_AS_ASSIGNEE)</code></li><li>taskdetailui --&gt; manager: <code>show validation error (&quot;Assignee cannot be assigned to QC their own task&quot;)</code></li><li>taskcontroller --&gt; taskdetailui: <code>400 Bad Request</code></li><li>taskservice -&gt;&gt; workspacememberrepos: <code>findByWorkspaceIdAndUserId(workspaceId, assigneeId)</code></li><li>workspacememberrepos --&gt; taskservice: <code>empty</code></li><li>taskservice --&gt; taskcontroller: <code>throw BusinessException (400 INVALID_ASSIGNEE)</code></li><li>taskcontroller --&gt; taskdetailui: <code>400 Bad Request</code></li><li>taskdetailui --&gt; manager: <code>show validation error (&quot;Selected assignee is not an active workspace member&quot;)</code></li><li>taskservice -&gt;&gt; workspacememberrepos: <code>findByWorkspaceIdAndUserId(workspaceId, assigneeId)</code></li><li>workspacememberrepos --&gt; taskservice: <code>assigneeMember</code></li><li>taskservice -&gt;&gt; workspacememberrepos: <code>findByWorkspaceIdAndUserId(workspaceId, qcAssigneeId)</code></li><li>workspacememberrepos --&gt; taskservice: <code>qcMember</code></li><li>taskservice -&gt;&gt; taskrepository: <code>save(task with assigneeId, qcAssigneeId, requiresClientApproval, status=ASSIGNED)</code></li><li>taskrepository --&gt; taskservice: <code>savedTask</code></li><li>taskservice --&gt; taskcontroller: <code>TaskResponse (status=ASSIGNED)</code></li><li>taskcontroller --&gt; taskdetailui: <code>200 OK (TaskResponse)</code></li><li>taskdetailui --&gt; manager: <code>show success toast (&quot;Task assigned successfully&quot;) &amp; update status badge to ASSIGNED</code></li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Xác thực</td><td>Token thiếu, hết hạn hoặc không hợp lệ</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Phân quyền</td><td>Vai trò người dùng không có quyền truy cập tính năng</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Kiểm tra dữ liệu</td><td>Dữ liệu đầu vào không hợp lệ hoặc xung đột trạng thái</td><td>400</td><td><code>BAD_REQUEST</code></td></tr><tr><td>Truy vấn</td><td>Không tìm thấy bản ghi đối tượng tương ứng</td><td>404</td><td><code>NOT_FOUND</code></td></tr></tbody></table>',10)])])}const h=t(r,[["render",i]]);export{u as __pageData,h as default};
